"""Tiny weather CLI. Commands are plain functions dispatched by name."""
import sys

from forecast.api import DailyClient


def cmd_today():
    row = DailyClient().daily(1)[0]
    print(f"{row['day']}: high {row['high']} low {row['low']}")


def cmd_alerts():
    print("no active alerts")


COMMANDS = {"today": cmd_today, "alerts": cmd_alerts}


def main(argv=None):
    argv = argv or sys.argv[1:]
    if not argv or argv[0] not in COMMANDS:
        print("usage: forecast [" + "|".join(sorted(COMMANDS)) + "]")
        return 1
    COMMANDS[argv[0]]()
    return 0

